output_text:
[
  {
    "id": "take_entrance_cart",
    "text": "A shopper must pick up the entrance cart before completing the trip.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_bay": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "pickup_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_bay",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entrance_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Shoppers are not allowed to carry merchandise by hand.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "pickup_items_only_with_cart",
    "text": "Items may only be picked up while the shopper has a cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "return_cart_to_0_1",
    "text": "After taking a cart, the shopper must return it at the cart-return counter at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "at_cart_return": "at(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_at_0_1": {
          "pre": {
            "and": [
              "at_cart_return",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_at_0_1"
    }
  },
  {
    "id": "no_cart_abandonment",
    "text": "A cart must not be left anywhere except at the designated cart-return cell (0,1).",
    "abstraction": {
      "state_properties": {
        "at_cart_return": "at(0,1)",
        "away_from_cart_return": {
          "not": "at_cart_return"
        }
      },
      "events": {
        "leave_cart_away_from_return": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "away_from_cart_return"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_away_from_return"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Shoppers may not leave the store while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "at_exit": "at(9,5)",
        "still_has_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "at_exit",
              "EXIT",
              "still_has_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "loaded_cart_must_be_returned",
    "text": "Once any required item has been placed in the cart, the loaded cart must eventually be returned at (0,1).",
    "abstraction": {
      "state_properties": {
        "at_cart_return": "at(0,1)"
      },
      "events": {
        "item_loaded_into_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "hasCart"
            ]
          },
          "post": "hasCart"
        },
        "return_loaded_cart": {
          "pre": {
            "and": [
              "at_cart_return",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_loaded_into_cart",
      "discharge": "return_loaded_cart"
    }
  },
  {
    "id": "no_carts_in_east_exit_corridor",
    "text": "Carts are not allowed in the eastern exit corridor beyond the shopping shelves.",
    "abstraction": {
      "state_properties": {
        "east_exit_corridor": {
          "or": [
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)"
          ]
        },
        "cart_in_east_exit_corridor": {
          "and": [
            "hasCart",
            "east_exit_corridor"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_east_exit_corridor"
    }
  }
]
